1	// THE GITHUB PORT. Every REST path this pack calls is spelled in this module and
2	// nowhere else: a caller names the OPERATION it wants — read this issue, swap this
3	// label, merge this pull request — and never the URL that performs it. That is
4	// what makes the outward edge countable and replaceable; a module that spelled its
5	// own path would be a second GitHub client nothing knows about.
6	//
7	// The transport is `gh(path) -> { status, json }`, made by `makeGh` and passed to
8	// every operation as its first argument. It stays an injected function rather than
9	// a bound client because the whole pack tests against a fake `gh`, and because the
10	// fleet planner supplies its own reader over a different token.
11	//
12	// A non-2xx returns `{ status, json: null }` rather than throwing, so a 404 (no
13	// release yet, missing file) is data, not an error. Callers that must not mistake
14	// a refusal for an answer read the STATUS — a 403 from a repo whose Actions cannot
15	// write puts a plausible object where the result should be.
16	//
17	// LABEL WRITES ARE GRANULAR, ALWAYS (docs/PRINCIPLES.md): add and remove NAMED
18	// labels (POST/DELETE), never write the label SET (PUT). A set-write replaces from
19	// a stale snapshot and clobbers concurrent transitions — a bug class GitHub's own
20	// CLI shipped (cli/cli#4861) — and with a scheduler run and several executors all
21	// moving labels at once, that is a correctness rule rather than a style preference.
22	
23	const API = process.env.GITHUB_API_URL || 'https://api.github.com';
24	
25	// The Action-side reader/writer. `packs/claudinite-tasks/` is the one place that
26	// legitimately uses the Action's `GITHUB_TOKEN` — everything session-side stays
27	// MCP-only (docs/PRINCIPLES.md).
28	//
29	// `path` is an API path beginning with `/` (e.g. `/repos/owner/name/commits`); the
30	// base URL and auth are applied here.
31	export function makeGh({ token = process.env.GITHUB_TOKEN, api = API, fetchImpl = fetch } = {}) {
32	  // `gh(path)` reads; `gh(path, { method, body })` writes (body JSON-encoded).
33	  return async function gh(path, { method = 'GET', body } = {}) {
34	    const res = await fetchImpl(`${api}${path}`, {
35	      method,
36	      headers: {
37	        accept: 'application/vnd.github+json',
38	        'x-github-api-version': '2022-11-28',
39	        ...(token ? { authorization: `Bearer ${token}` } : {}),
40	        'user-agent': 'claudinite-scheduler',
41	        ...(body ? { 'content-type': 'application/json' } : {}),
42	      },
43	      ...(body ? { body: JSON.stringify(body) } : {}),
44	    });
45	    let json = null;
46	    try { json = await res.json(); } catch { json = null; }
47	    return { status: res.status, json };
48	  };
49	}
50	
51	// The same call for a caller that holds a token rather than a made client — the
52	// delivery lane, which is handed one per run. One implementation of the headers,
53	// so a client the landing lane uses cannot drift from the one the executor uses.
54	export async function restCall(token, path, { method = 'GET', body, api = API, fetchImpl = fetch } = {}) {
55	  const res = await fetchImpl(`${api}${path}`, {
56	    method,
57	    headers: {
58	      authorization: `Bearer ${token}`,
59	      accept: 'application/vnd.github+json',
60	      'x-github-api-version': '2022-11-28',
61	      ...(body ? { 'content-type': 'application/json' } : {}),
62	    },
63	    body: body ? JSON.stringify(body) : undefined,
64	  });
65	  let json = null;
66	  try { json = await res.json(); } catch { /* empty body */ }
67	  return { status: res.status, json };
68	}
69	
70	// The GraphQL endpoint, for the two mutations REST does not offer. Returns the
71	// parsed body; the caller decides what an `errors` array means.
72	export async function graphqlCall(token, query, variables, { api = API, fetchImpl = fetch } = {}) {
73	  const res = await fetchImpl(`${api}/graphql`, {
74	    method: 'POST',
75	    headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json' },
76	    body: JSON.stringify({ query, variables }),
77	  });
78	  return res.json().catch(() => null);
79	}
80	
81	// --- issues -------------------------------------------------------------------
82	
83	export const readIssue = async (gh, repo, number) => {
84	  const { status, json } = await gh(`/repos/${repo}/issues/${number}`);
85	  return status === 200 ? json : null;
86	};
87	
88	// The same read, with the status kept — for a caller that must tell "closed" from
89	// "could not be read".
90	export const getIssue = (gh, repo, number) => gh(`/repos/${repo}/issues/${number}`);
91	
92	// Replace an issue's body. The whole body, because that is the only shape the API
93	// offers — every caller reshapes the text it read rather than composing a new one.
94	export const setIssueBody = (gh, repo, number, body) =>
95	  gh(`/repos/${repo}/issues/${number}`, { method: 'PATCH', body: { body } });
96	
97	export const setIssueTitle = (gh, repo, number, title) =>
98	  gh(`/repos/${repo}/issues/${number}`, { method: 'PATCH', body: { title } });
99	
100	// The raw issue PATCH and POST, for a caller that reads the status itself rather
101	// than taking one of the shaped writes above — the tracker, which fails soft on one
102	// call and loud on the next and so must see both.
103	export const patchIssue = (gh, repo, number, body) =>
104	  gh(`/repos/${repo}/issues/${number}`, { method: 'PATCH', body });
105	
106	export const reopenIssue = (gh, repo, number) =>
107	  gh(`/repos/${repo}/issues/${number}`, { method: 'PATCH', body: { state: 'open' } });
108	
109	export const postIssue = (gh, repo, body) =>
110	  gh(`/repos/${repo}/issues`, { method: 'POST', body });
111	
112	export const closeIssue = (gh, repo, number, stateReason = 'completed') =>
113	  gh(`/repos/${repo}/issues/${number}`, { method: 'PATCH', body: { state: 'closed', state_reason: stateReason } });
114	
115	export async function createIssue(gh, repo, { title, body, labels = [] }) {
116	  const { status, json } = await gh(`/repos/${repo}/issues`, { method: 'POST', body: { title, body, labels } });
117	  // The STATUS is read, not just the body: a 403 from a repo whose Actions cannot
118	  // create issues puts an error object where the issue should be, and a body-only
119	  // destructure turns that refusal into a plausible object whose `.number` is
120	  // simply undefined.
121	  return { status, number: status >= 200 && status < 300 ? json?.number ?? null : null, json };
122	}
123	
124	// One page of the repo's open issues, oldest first — the order the queue reads its
125	// items in, so a page boundary cannot reorder them.
126	export const listOpenIssuesPage = (gh, repo, page) =>
127	  gh(`/repos/${repo}/issues?state=open&sort=created&direction=asc&per_page=100&page=${page}`);
128	
129	// One page of recently closed issues, newest first — a bounded look back over
130	// settled items rather than the whole history.
131	export const listClosedIssuesPage = (gh, repo, page) =>
132	  gh(`/repos/${repo}/issues?state=closed&sort=updated&direction=desc&per_page=100&page=${page}`);
133	
134	// The issues listing under a caller-composed query string (already encoded): the
135	// label/state/since filters each reader needs, without this module having to know
136	// every combination.
137	export const listIssuesByQuery = (gh, repo, query) => gh(`/repos/${repo}/issues?${query}`);
138	
139	// Issue search across the repo. Search is eventually consistent and rate-limited
140	// separately from the REST API, which is why the callers here treat an
141	// unsuccessful search as "no answer" rather than "nothing found".
142	export const searchIssues = (gh, query) => gh(`/search/issues?q=${query}&per_page=100`);
143	
144	// --- labels -------------------------------------------------------------------
145	
146	// Ensure every label exists before any is applied. Load-bearing, not cosmetic:
147	// GitHub does not create a label when you apply one (the issues API 422s on an
148	// unknown label), so the thing that assigns a label must guarantee it first.
149	// Idempotent (201 created / 422 already exists are both success) and self-healing
150	// — a deleted label reappears on the next run.
151	export async function ensureLabels(gh, repo, labels) {
152	  for (const { name, color, description } of labels) {
153	    const res = await gh(`/repos/${repo}/labels`, { method: 'POST', body: { name, color, description } });
154	    if (res.status === 201) continue;                       // created to spec — nothing further
155	    if (res.status === 422) {
156	      // The NAME is taken; that says nothing about the colour or description. A
157	      // label GitHub auto-created (applying an unknown name to an issue mints it
158	      // grey `ededed`, no description) would keep those defaults for good, because
159	      // POST 422s forever. So reconcile the shape, not just the existence — that
160	      // is what makes the self-healing claim above true for drift and not only for
161	      // deletion. PATCH is idempotent: an already-correct label is a no-op write.
162	      const fix = await gh(`/repos/${repo}/labels/${encodeURIComponent(name)}`, {
163	        method: 'PATCH', body: { color, description },
164	      });
165	      if (fix.status !== 200) console.log(`! could not reconcile label "${name}": ${fix.status}`);
166	      continue;
167	    }
168	    console.log(`! could not ensure label "${name}": ${res.status}`);
169	  }
170	}
171	
172	export const addLabel = (gh, repo, number, name) =>
173	  gh(`/repos/${repo}/issues/${number}/labels`, { method: 'POST', body: { labels: [name] } });
174	
175	// A label that is already absent 404s; that is the desired end state, so it is
176	// success. Nothing here reads the response beyond reporting it.
177	export const removeLabel = (gh, repo, number, name) =>
178	  gh(`/repos/${repo}/issues/${number}/labels/${encodeURIComponent(name)}`, { method: 'DELETE' });
179	
180	// The swap every state transition makes. Remove-then-add, and NOT atomic —
181	// GitHub has no atomic label swap. That is safe because labels are visibility and
182	// the pick filter, never the arbiter (the claim comments are); what a torn swap
183	// CAN leave is an open item wearing no state label at all, which the janitor
184	// repairs (docs/PRINCIPLES.md).
185	export async function swapLabel(gh, repo, number, from, to) {
186	  await removeLabel(gh, repo, number, from);
187	  return addLabel(gh, repo, number, to);
188	}
189	
190	// --- comments -----------------------------------------------------------------
191	
192	export const comment = (gh, repo, number, body) =>
193	  gh(`/repos/${repo}/issues/${number}/comments`, { method: 'POST', body: { body } });
194	
195	// The ONE sanctioned edit to a comment, and the reason the arbitration record is
196	// no longer strictly append-only: an executor striking its OWN claim on the way
197	// out (docs/PRINCIPLES.md). Only a claim's author ever edits it, so a claim can be
198	// withdrawn but never forged earlier, and comment ids still give the total order
199	// arbitration reads.
200	export const editComment = (gh, repo, commentId, body) =>
