1	// The executor loop end to end against a fake GitHub — pick, claim, evaluate,
2	// code-work, hand off, converge. The pure rules are tested beside this; what this
3	// pins is that the SHELL actually drives them to a terminal state, which is the
4	// thing a fixture over the rules alone can never say.
5	
6	import { test } from 'node:test';
7	import assert from 'node:assert/strict';
8	import { runExecutor } from '../../src/execute/loop.mjs';
9	import { parseWorkItemBody } from '../../src/items/work-item.mjs';
10	import { normalizeTaskDeclaration } from '../../src/contract/task-contract.mjs';
11	
12	const SCHEDULE = { dailyHour: 4, weeklyDay: 'Sun', monthlyDay: 1 };
13	const CONFIG = { taskScheduler: SCHEDULE, packConfig: {} };
14	
15	// A fake repo: issues with labels, bodies, comments and state, driven through the
16	// same REST paths the shell calls.
17	function fakeRepo(issues = [], pulls = []) {
18	  const state = {
19	    issues: issues.map((i) => ({ comments: [], state: 'open', ...i })), commentSeq: 100, calls: [],
20	    pulls: pulls.map((p) => ({ comments: [], state: 'open', ...p })),
21	  };
22	  const find = (n) => state.issues.find((i) => i.number === n);
23	  const findPull = (n) => state.pulls.find((p) => p.number === n);
24	  const gh = async (path, { method = 'GET', body } = {}) => {
25	    state.calls.push(`${method} ${path}`);
26	    let m;
27	    if (method === 'GET' && /^\/repos\/[^/]+\/[^/]+\/pulls\?/.test(path)) {
28	      return { status: 200, json: state.pulls.filter((p) => p.state === 'open') };
29	    }
30	    if ((m = /^\/repos\/[^/]+\/[^/]+\/pulls\/(\d+)$/.exec(path))) {
31	      const pr = findPull(Number(m[1]));
32	      if (!pr) return { status: 404, json: null };
33	      if (method === 'PATCH') Object.assign(pr, body);
34	      return { status: 200, json: pr };
35	    }
36	    if (/\/git\/refs\/heads\//.test(path)) return { status: 204, json: null };
37	    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/comments/.exec(path)) && !find(Number(m[1])) && findPull(Number(m[1]))) {
38	      if (method === 'POST') findPull(Number(m[1])).comments.push({ body: body.body });
39	      return { status: 201, json: {} };
40	    }
41	    if (method === 'GET' && /^\/repos\/[^/]+\/[^/]+\/issues\?/.test(path)) {
42	      const page = Number(/[?&]page=(\d+)/.exec(path)?.[1] ?? 1); // NOT /page=/ — that matches per_page
43	      return { status: 200, json: page === 1 ? state.issues.filter((i) => i.state === 'open') : [] };
44	    }
45	    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/comments\/(\d+)$/.exec(path))) {
46	      const id = Number(m[1]);
47	      for (const issue of state.issues) {
48	        const c = issue.comments.find((x) => x.id === id);
49	        if (c) { if (method === 'PATCH') c.body = body.body; return { status: 200, json: c }; }
50	      }
51	      return { status: 404, json: null };
52	    }
53	    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/comments/.exec(path))) {
54	      const issue = find(Number(m[1]));
55	      if (method === 'POST') {
56	        issue.comments.push({ id: (state.commentSeq += 1), body: body.body });
57	        issue.updated_at = 'now';
58	        return { status: 201, json: {} };
59	      }
60	      return { status: 200, json: issue.comments };
61	    }
62	    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/labels\/(.+)$/.exec(path))) {
63	      const issue = find(Number(m[1]));
64	      issue.labels = issue.labels.filter((l) => l !== decodeURIComponent(m[2]));
65	      return { status: 200, json: {} };
66	    }
67	    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/labels$/.exec(path))) {
68	      const issue = find(Number(m[1]));
69	      issue.labels.push(...body.labels);
70	      return { status: 200, json: {} };
71	    }
72	    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)$/.exec(path))) {
73	      const issue = find(Number(m[1]));
74	      if (method === 'PATCH') Object.assign(issue, body);
75	      return { status: 200, json: issue };
76	    }
77	    return { status: 404, json: null };
78	  };
79	  return { state, gh, find, findPull };
80	}
81	
82	const workItem = (number, task, labels, body = null) => ({
83	  number, title: `[claudinite-work] p/${task}`, labels,
84	  body: body ?? `packs/p/tasks/${task}/task.md\n\nExecute the Claudinite task above.\n`,
85	  created_at: '2026-08-14T04:00:00Z', updated_at: '2026-08-14T04:00:00Z',
86	});
87	
88	// `taskDir` is a REAL directory: the executor probes it before it runs anything,
89	// because a task can be deleted out from under an item this run already queued.
90	// `gate` is how a fixture states its verdict: the declarative expression is the
91	// only precondition mechanism, so a fixture that must decline (or throw) does it
92	// through a task-local term, exactly as a real task would.
93	const term = (holds) => new Map([['gate', { signals: [], holds }]]);
94	const RUNS = term(() => ({ holds: true }));
95	const task = (id, decl = {}, terms = RUNS) => ({
96	  pack: 'p', id, taskDir: process.cwd(), taskPath: `packs/p/tasks/${id}/task.md`,
97	  decl: normalizeTaskDeclaration({ id, frequency: 'daily', agent_model: 'sonnet', preconditions: ['gate'], expected_outcome: 'fresh_pr', ...decl }),
98	  terms,
99	});
100	
101	// `random` is pinned ascending so a fixture with several pickable items picks the
102	// FIRST one it lists — production's draw is random (PRINCIPLES.md) and a test that let it
103	// vary would be a coin flip, not a test.
104	const ascendingDraw = () => { let n = 0; return () => (n += 1) / 1000; };
105	
106	const drive = (repo, tasks, over = {}) => runExecutor({
107	  gh: repo.gh, repo: 'o/r', root: '/tmp', config: CONFIG, tasks,
108	  executorId: 'E1', now: () => new Date('2026-08-14T04:20:00Z'), random: ascendingDraw(),
109	  collectSignalsFor: async () => ({}),
110	  runTaskCodeWork: async () => ({ ok: true, agentRequested: false }),
111	  invokeAgent: async () => ({ ok: true, sessionId: 's-1' }),
112	  log: () => {},
113	  ...over,
114	});
115	
116	// --- the target (PRINCIPLES.md) ---------------------------------------------------
117	// The executor decides which branch and pull request the run works on ONCE, after
118	// the precondition's go and before code-work, and both phases are handed the
119	// answer: code-work as environment, the agent as item fields.
120	
121	test('code-work is handed the target the executor resolved, minted under the task\'s prefix', async () => {
122	  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])]);
123	  const seen = [];
124	  await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 })], {
125	    runTaskCodeWork: async (t, { target }) => { seen.push(target); return { ok: true, agentRequested: false }; },
126	  });
127	  assert.equal(seen.length, 1);
128	  assert.equal(seen[0].mode, 'fresh');
129	  assert.match(seen[0].branch, /^claudinite\/p\/a\/2026-08-14-[a-z0-9]+$/);
130	  assert.ok(!repo.state.calls.some((c) => /\/pulls/.test(c)), 'a fresh_pr target reads no pull request');
131	});
132	
