573	// The lease's whole point, driven through the shell: an executor that is not this
574	// episode's earliest claimant touches that item's state not at all. Under the
575	// batched drain it does NOT end its run — the winner owns that ONE item, not the
576	// queue — so it moves to the next pickable item and leaves the loser's behind.
577	test('an executor that loses the lease leaves that item to its winner and drains the rest', async () => {
578	  const rival = { id: 1, body: '<!-- claudinite-claim -->\nClaimed by executor `E0` at earlier.' };
579	  const repo = fakeRepo([
580	    { ...workItem(1, 'a', ['task:status:waiting-for-executor']), comments: [rival] },
581	    workItem(2, 'b', ['task:status:waiting-for-executor']),
582	  ]);
