584	  assert.deepEqual(done, [{ issue: 2, outcome: 'task:status:done' }], 'the item it did win, it settled');
585	  assert.equal(repo.find(1).state, 'open', 'the lost item is the winner\'s to converge');
586	  assert.equal(repo.find(2).state, 'closed');
587	});
