589	// --- one run drains the queue (docs/PRINCIPLES.md, S34/S65) -------------------
590	//
591	// The reversal of one-item-per-run (docs/PRINCIPLES.md), and the reason is the bill: Actions rounds each job's
592	// minutes up, so a run per item bought a whole invocation — checkout, setup,
593	// rounding — for each. A run now settles what is pickable, one item at a time.
594	
595	test('a run drains every pickable item, one at a time', async () => {
596	  const repo = fakeRepo([
597	    workItem(1, 'a', ['task:status:waiting-for-executor']),
598	    workItem(2, 'b', ['task:status:waiting-for-executor']),
599	    workItem(3, 'c', ['task:status:waiting-for-executor']),
600	  ]);
601	  // Three DIFFERENT titles, so nothing here is serialized by the same-title
602	  // mutex: all three are pickable at once and ONE run settles all three.
603	  const agentless = (id) => task(id, { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 });
604	  const done = await drive(repo, ['a', 'b', 'c'].map(agentless));
605	  assert.deepEqual(done.map((d) => d.issue).sort(), [1, 2, 3]);
606	  for (const n of [1, 2, 3]) assert.equal(repo.find(n).state, 'closed', `#${n} converged in the same run`);
607	});
