609	// Serial, not concurrent: the run boundary moved, the occupancy model did not
610	// (PRINCIPLES.md). Each item's work step completes before the next item is claimed —
611	// so a code-work that observed an overlap would be the regression.
612	test('a drained run never runs two items\' work at once', async () => {
613	  const repo = fakeRepo([workItem(1, 'a', ['task:ready']), workItem(2, 'b', ['task:ready'])]);
614	  let inFlight = 0; let overlapped = false;
615	  const agentless = (id) => task(id, { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 });
616	  await drive(repo, ['a', 'b'].map(agentless), {
617	    runTaskCodeWork: async () => {
618	      inFlight += 1;
619	      if (inFlight > 1) overlapped = true;
620	      await new Promise((r) => setTimeout(r, 1));
621	      inFlight -= 1;
622	      return { ok: true, agentRequested: false };
623	    },
624	  });
625	  assert.equal(overlapped, false);
626	});
627	
628	// A handed-off item leaves the executor's occupancy at the hand-off (PRINCIPLES.md) — so
629	// the run goes straight on to the next item rather than waiting for a session
630	// it will never hear from.
631	test('a hand-off ends that item\'s occupancy and the run keeps draining', async () => {
632	  const repo = fakeRepo([workItem(1, 'a', ['task:ready']), workItem(2, 'b', ['task:ready'])]);
633	  const done = await drive(repo, [
634	    task('a'),
635	    task('b', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 }),
636	  ]);
637	  assert.deepEqual(done, [{ issue: 1, outcome: 'agent' }, { issue: 2, outcome: 'task:status:done' }]);
638	});
