640	// THE REVERT'S OWN HAZARD, which only the batched run has. A post-claim revert
641	// (F15) puts the item back to `task:ready` — and a run that re-reads the queue
642	// to pick its next item would find exactly what it just returned, claim it,
643	// revert it again, forever. The stand-down set is what makes a revert a
644	// hand-off to the winner rather than a loop.
645	test('an item this run reverted is never re-picked by it (F15 under the drain)', async () => {
646	  const repo = fakeRepo([
647	    workItem(1, 'a', ['task:ready']),
648	    workItem(2, 'b', ['task:ready']),
649	    { ...workItem(99, 'a', ['task:executing']),
650	      comments: [{ id: 1, body: '<!-- claudinite-claim -->\nClaimed by executor `E0` at earlier.' }] },
651	  ]);
652	  // The stale-read race, exactly: the pick sees a clean queue, and by the time
653	  // the post-claim re-verify reads again, a twin of #1 is running under an
654	  // EARLIER claim. Nothing but a second read can produce this — which is why
655	  // the rule-level fixture beside this cannot stand in for it.
656	  // Only the post-claim re-verify's read sees the twin: the pick before it
657	  // predates the twin's claim, and by the next pick the twin has settled and is
658	  // gone. So nothing but the stand-down set stops this run re-claiming #1 —
659	  // the pick filter, reading a queue with no twin in it, would hand it straight
660	  // back. A revert is this run losing an arbitration, not a retry.
661	  let lists = 0;
662	  const gh = async (path, opts = {}) => {
663	    const res = await repo.gh(path, opts);
664	    if ((opts.method ?? 'GET') === 'GET' && /\/issues\?/.test(path) && Array.isArray(res.json)) {
665	      lists += 1;
666	      if (lists !== 2) return { ...res, json: res.json.filter((i) => i.number !== 99) };
667	    }
668	    return res;
669	  };
670	  const agentless = (id) => task(id, { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 });
671	  const done = await drive(repo, ['a', 'b'].map(agentless), { gh });
672	  assert.ok(repo.find(1).labels.includes('task:status:waiting-for-executor'), '#1 went back to the queue');
673	  assert.equal(done.filter((d) => d.issue === 1).length, 0, '#1 was not run by the reverting executor');
674	  // and the run did not stop at the revert either — it went on and drained #2
675	  assert.deepEqual(done, [{ issue: 2, outcome: 'task:status:done' }]);
676	});
