678	// --- the operator hold, between items (PRINCIPLES.md, S37) ---------------------------
679	//
680	// `vars.*` reaches the env at run START only, so a drain that outlives the hold's
681	// arrival can see it only by asking. It stops PICKING; the item it holds finishes.
682	test('a hold arriving mid-drain stops the next pick and leaves the queue untouched', async () => {
683	  const repo = fakeRepo([
684	    workItem(1, 'a', ['task:ready']),
685	    workItem(2, 'b', ['task:ready']),
686	    workItem(3, 'c', ['task:ready']),
687	  ]);
688	  const lines = [];
689	  const agentless = (id) => task(id, { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 });
690	  let asked = 0;
691	  const done = await drive(repo, ['a', 'b', 'c'].map(agentless), {
692	    heldNow: async () => (asked += 1) >= 2, // held from the second boundary on
693	    log: (l) => lines.push(l),
694	  });
695	  assert.deepEqual(done.map((d) => d.issue), [1, 2], 'the item in hand finished; nothing new was picked');
696	  assert.equal(repo.find(3).state, 'open');
697	  assert.deepEqual(repo.find(3).labels, ['task:ready'], 'frozen exactly as it was — no label touched');
698	  assert.ok(lines.some((l) => l.includes('CLAUDINITE_TASKS_SUSPEND_ALL')), lines.join('\n'));
699	});
700	
701	// The read costs an API call, so a run with nothing left to do must not spend it:
702	// the hold is asked between items, never after the last one.
703	test('a run that drained the queue asks the hold once per settle, not once more', async () => {
704	  const repo = fakeRepo([workItem(1, 'a', ['task:ready'])]);
705	  let asked = 0;
706	  await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 })], {
707	    heldNow: async () => { asked += 1; return false; },
708	  });
709	  assert.equal(asked, 1);
710	});
711	
712	// --- F24: letting go of an open item kills your claim --------------------------
713	//
714	// A single-executor test cannot see this class: an executor beats its own stale
715	// claim by id equality, so the item runs and the leak stays invisible. What
716	// exposes it is a SECOND executor arriving after the first let the item go — the
717	// shape the whole burst missed and live traffic found.
718	
719	// The ROLLED half of F24 retired with the roll itself (#1115): a decline now
720	// CLOSES its item, nothing re-claims a closed issue, and the silent-episode
721	// class narrows to the park — the test below.
722	
723	test('a second executor wins immediately on a PARKED item a human re-queued (F24)', async () => {
724	  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])]);
725	  const agentic = task('a');
726	
727	  // E1 claims, hands off, the endpoint refuses → parked needs-human, claim struck.
728	  await drive(repo, [agentic], { invokeAgent: async () => ({ ok: false, answered: true, error: 'no endpoint' }) });
729	  assert.ok(repo.find(1).labels.some((l) => l.startsWith('task:status:needs-human-')));
730	
731	  // The sanctioned re-queue, exactly as the park's own comment instructs (F7):
732	  // drop needs-human, add task:status:waiting-for-executor. Nothing else — no marker, no cleanup.
733	  repo.find(1).labels = ['task:status:waiting-for-executor'];
734	  const done = await drive(repo, [agentic], { executorId: 'E2' });
735	
736	  assert.deepEqual(done, [{ issue: 1, outcome: 'agent' }],
737	    'the item must be claimable again — a park that leaves its claim standing livelocks forever');
738	});
739	
740	test('a losing claimant strikes its own claim too — otherwise it owns the NEXT episode (F24)', async () => {
741	  // A rival already holds this episode; E1 claims, loses, and walks away.
742	  const rival = { id: 50, body: '<!-- claudinite-claim -->\nClaimed by executor `E9` at t.' };
743	  const repo = fakeRepo([{ ...workItem(1, 'a', ['task:status:waiting-for-executor']), comments: [rival] }]);
744	  const agentless = task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 });
745	
746	  await drive(repo, [agentless]);
747	  assert.equal(repo.find(1).state, 'open', 'E1 left the item to its holder');
748	
749	  // E9's tenure ends — reclaimed by the leash — which opens a fresh episode.
750	  // E1's abandoned claim is younger than E9's, so unless it was struck it is now
751	  // the earliest of the new episode and nothing can ever take the item.
752	  const issue = repo.find(1);
753	  issue.comments.push({ id: 60, body: '<!-- claudinite-episode -->\nreclaimed: executor went silent' });
754	  issue.labels = ['task:status:waiting-for-executor'];
755	
756	  const done = await drive(repo, [agentless], { executorId: 'E2' });
757	  assert.deepEqual(done, [{ issue: 1, outcome: 'task:status:done' }],
758	    'E2 must win the fresh episode — a loser\'s leftover claim must not outlive its own episode');
759	});
760	
761	// --- the dispatch write itself -------------------------------------------------
762	//
763	// The chain's one non-issue write. A 204 is the ONLY success: `actions: write`
764	// missing returns a 403 with a body that reads like any other response, so a
765	// caller that judged the body would report a chain it never started.
766	
767	test('dispatchWorkflow judges the POST by status, never by its body', async () => {
768	  const { dispatchWorkflow } = await import('../../src/world/github.mjs');
769	  const seen = [];
770	  const gh = async (path, opts) => {
771	    seen.push({ path, ...opts });
772	    return path.includes('denied')
773	      ? { status: 403, json: { message: 'Resource not accessible by integration' } }
774	      : { status: 204, json: null };
775	  };
776	  assert.deepEqual(await dispatchWorkflow(gh, 'o/r', 'claudinite-executor.yml', 'main'),
777	    { ok: true, status: 204 });
778	  assert.deepEqual(seen[0], {
779	    path: '/repos/o/r/actions/workflows/claudinite-executor.yml/dispatches',
780	    method: 'POST',
781	    body: { ref: 'main' },
782	  });
783	  assert.deepEqual(await dispatchWorkflow(gh, 'o/denied', 'claudinite-executor.yml', 'main'),
784	    { ok: false, status: 403 });
785	});
786	
787	// --- the durable record, and the release a close performs (docs/PRINCIPLES.md) -----
788	//
789	// The executor converges the agentless majority itself, and for those runs the
790	// item is the only trace that outlives the Actions log.
791	
792	test('an executor close writes the execution record onto the item', async () => {
793	  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])]);
794	  await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 })]);
795	  assert.match(repo.find(1).comments.at(-1).body, /claudinite-task-exec v1 p\/a \[#1\] success/);
796	});
797	
798	test('a park in the failure lane records the run as failed', async () => {
799	  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])]);
800	  await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 })], {
801	    runTaskCodeWork: async () => ({ ok: false, why: 'boom' }),
802	  });
803	  assert.match(repo.find(1).comments.at(-1).body, /claudinite-task-exec v1 p\/a \[#1\] failed/);
804	});
805	
806	// An approval park is a run that SUCCEEDED and left a PR — neither `success` (the
807	// item is open) nor `failed` (nothing broke). Absence is the honest answer.
808	test('an approval park writes no record at all', async () => {
809	  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])]);
810	  await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 })], {
811	    runTaskCodeWork: async () => ({ ok: true, agentRequested: false, delivered: ['PR: #7 (open)'], openPr: 7 }),
812	  });
813	  assert.doesNotMatch(repo.find(1).comments.at(-1).body, /claudinite-task-exec/);
814	});
815	
816	// A close writes only to the item it holds (docs/PRINCIPLES.md; #1373 reversed an earlier attempt):
817	// releasing a dependent is the scheduler run's readiness job alone, never a
818	// close's.
819	test('an executor close leaves the dependent it was holding still blocked', async () => {
820	  const dependent = {
821	    ...workItem(2, 'b', ['task:status:blocked']),
822	    body: 'packs/p/tasks/b/task.md\n\nBlocked-by: #1\n',
823	  };
824	  const repo = fakeRepo([workItem(1, 'a', ['task:ready']), dependent]);
825	  const agentless = (id) => task(id, { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 });
826	  const done = await drive(repo, ['a', 'b'].map(agentless));
827	  assert.deepEqual(done.map((d) => d.issue), [1], 'the dependent was never picked up in this run');
828	  assert.equal(repo.find(1).state, 'closed');
829	  assert.deepEqual(repo.find(2).labels, ['task:status:blocked']);
830	  assert.equal(repo.find(2).state, 'open');
831	});
832	
833	// The beat, driven through the shell: a work step long enough to need one gets
834	// one, on the item, from the executor holding it.
835	test('a long work step leaves heartbeats on its own item', async () => {
836	  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])]);
837	  const beatsSoFar = () => repo.find(1).comments.filter((c) => c.body.includes('<!-- claudinite-heartbeat -->'));
838	  await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 })], {
839	    heartbeatMs: 5,
840	    // The step holds itself open UNTIL the beat has landed twice, rather than
841	    // sleeping long enough that it probably has. A fixed window against a 5ms
842	    // interval is a race the loaded machine wins: under the full suite at eight
843	    // workers this read one beat and failed on ~3 runs in 4. The ceiling is what
844	    // keeps a heartbeat that never fires a failed assertion rather than a hang.
845	    runTaskCodeWork: async () => {
846	      const deadline = Date.now() + 5000;
847	      while (beatsSoFar().length < 2 && Date.now() < deadline) await new Promise((r) => setTimeout(r, 5));
848	      return { ok: true, agentRequested: false };
849	    },
850	  });
851	  const beats = beatsSoFar();
852	  assert.ok(beats.length >= 2, `the item stayed live through the work (got ${beats.length})`);
853	  assert.match(beats[0].body, /executor `E1`/);
854	});
