// The executor loop end to end against a fake GitHub — pick, claim, evaluate,
// code-work, hand off, converge. The pure rules are tested beside this; what this
// pins is that the SHELL actually drives them to a terminal state, which is the
// thing a fixture over the rules alone can never say.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { runExecutor } from '../../src/execute/loop.mjs';
import { parseWorkItemBody } from '../../src/items/work-item.mjs';
import { normalizeTaskDeclaration } from '../../src/contract/task-contract.mjs';

const SCHEDULE = { dailyHour: 4, weeklyDay: 'Sun', monthlyDay: 1 };
const CONFIG = { taskScheduler: SCHEDULE, packConfig: {} };

// A fake repo: issues with labels, bodies, comments and state, driven through the
// same REST paths the shell calls.
function fakeRepo(issues = [], pulls = []) {
  const state = {
    issues: issues.map((i) => ({ comments: [], state: 'open', ...i })), commentSeq: 100, calls: [],
    pulls: pulls.map((p) => ({ comments: [], state: 'open', ...p })),
  };
  const find = (n) => state.issues.find((i) => i.number === n);
  const findPull = (n) => state.pulls.find((p) => p.number === n);
  const gh = async (path, { method = 'GET', body } = {}) => {
    state.calls.push(`${method} ${path}`);
    let m;
    if (method === 'GET' && /^\/repos\/[^/]+\/[^/]+\/pulls\?/.test(path)) {
      return { status: 200, json: state.pulls.filter((p) => p.state === 'open') };
    }
    if ((m = /^\/repos\/[^/]+\/[^/]+\/pulls\/(\d+)$/.exec(path))) {
      const pr = findPull(Number(m[1]));
      if (!pr) return { status: 404, json: null };
      if (method === 'PATCH') Object.assign(pr, body);
      return { status: 200, json: pr };
    }
    if (/\/git\/refs\/heads\//.test(path)) return { status: 204, json: null };
    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/comments/.exec(path)) && !find(Number(m[1])) && findPull(Number(m[1]))) {
      if (method === 'POST') findPull(Number(m[1])).comments.push({ body: body.body });
      return { status: 201, json: {} };
    }
    if (method === 'GET' && /^\/repos\/[^/]+\/[^/]+\/issues\?/.test(path)) {
      const page = Number(/[?&]page=(\d+)/.exec(path)?.[1] ?? 1); // NOT /page=/ — that matches per_page
      return { status: 200, json: page === 1 ? state.issues.filter((i) => i.state === 'open') : [] };
    }
    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/comments\/(\d+)$/.exec(path))) {
      const id = Number(m[1]);
      for (const issue of state.issues) {
        const c = issue.comments.find((x) => x.id === id);
        if (c) { if (method === 'PATCH') c.body = body.body; return { status: 200, json: c }; }
      }
      return { status: 404, json: null };
    }
    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/comments/.exec(path))) {
      const issue = find(Number(m[1]));
      if (method === 'POST') {
        issue.comments.push({ id: (state.commentSeq += 1), body: body.body });
        issue.updated_at = 'now';
        return { status: 201, json: {} };
      }
      return { status: 200, json: issue.comments };
    }
    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/labels\/(.+)$/.exec(path))) {
      const issue = find(Number(m[1]));
      issue.labels = issue.labels.filter((l) => l !== decodeURIComponent(m[2]));
      return { status: 200, json: {} };
    }
    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/labels$/.exec(path))) {
      const issue = find(Number(m[1]));
      issue.labels.push(...body.labels);
      return { status: 200, json: {} };
    }
    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)$/.exec(path))) {
      const issue = find(Number(m[1]));
      if (method === 'PATCH') Object.assign(issue, body);
      return { status: 200, json: issue };
    }
    return { status: 404, json: null };
  };
  return { state, gh, find, findPull };
}

const workItem = (number, task, labels, body = null) => ({
  number, title: `[claudinite-work] p/${task}`, labels,
  body: body ?? `packs/p/tasks/${task}/task.md\n\nExecute the Claudinite task above.\n`,
  created_at: '2026-08-14T04:00:00Z', updated_at: '2026-08-14T04:00:00Z',
});

// `taskDir` is a REAL directory: the executor probes it before it runs anything,
// because a task can be deleted out from under an item this run already queued.
// `gate` is how a fixture states its verdict: the declarative expression is the
// only precondition mechanism, so a fixture that must decline (or throw) does it
// through a task-local term, exactly as a real task would.
const term = (holds) => new Map([['gate', { signals: [], holds }]]);
const RUNS = term(() => ({ holds: true }));
const task = (id, decl = {}, terms = RUNS) => ({
  pack: 'p', id, taskDir: process.cwd(), taskPath: `packs/p/tasks/${id}/task.md`,
  decl: normalizeTaskDeclaration({ id, frequency: 'daily', agent_model: 'sonnet', preconditions: ['gate'], expected_outcome: 'fresh_pr', ...decl }),
  terms,
});

// `random` is pinned ascending so a fixture with several pickable items picks the
// FIRST one it lists — production's draw is random (PRINCIPLES.md) and a test that let it
// vary would be a coin flip, not a test.
const ascendingDraw = () => { let n = 0; return () => (n += 1) / 1000; };

const drive = (repo, tasks, over = {}) => runExecutor({
  gh: repo.gh, repo: 'o/r', root: '/tmp', config: CONFIG, tasks,
  executorId: 'E1', now: () => new Date('2026-08-14T04:20:00Z'), random: ascendingDraw(),
  collectSignalsFor: async () => ({}),
  runTaskCodeWork: async () => ({ ok: true, agentRequested: false }),
  invokeAgent: async () => ({ ok: true, sessionId: 's-1' }),
  log: () => {},
  ...over,
});

// --- the target (PRINCIPLES.md) ---------------------------------------------------
// The executor decides which branch and pull request the run works on ONCE, after
// the precondition's go and before code-work, and both phases are handed the
// answer: code-work as environment, the agent as item fields.

test('code-work is handed the target the executor resolved, minted under the task\'s prefix', async () => {
  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])]);
  const seen = [];
  await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 })], {
    runTaskCodeWork: async (t, { target }) => { seen.push(target); return { ok: true, agentRequested: false }; },
  });
  assert.equal(seen.length, 1);
  assert.equal(seen[0].mode, 'fresh');
  assert.match(seen[0].branch, /^claudinite\/p\/a\/2026-08-14-[a-z0-9]+$/);
  assert.ok(!repo.state.calls.some((c) => /\/pulls/.test(c)), 'a fresh_pr target reads no pull request');
});

test('a supersede run closes the pull requests it was told to, once its own exists', async () => {
  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])], [{ number: 3, head: { ref: 'claudinite/p/a/2026-08-13-old', sha: 'x' } }]);
  await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60, expected_outcome: 'supersede_existing_pr' })], {
    resolveTargetFor: async () => ({ mode: 'fresh', branch: 'claudinite/p/a/2026-08-14-new', pr: null, supersedes: [3], landed: null, reason: 'r' }),
    runTaskCodeWork: async () => ({ ok: true, agentRequested: false, delivered: ['PR: #7 (open)'], openPr: 7, deliveredPr: 7 }),
  });
  assert.equal(repo.findPull(3).state, 'closed');
  assert.match(repo.findPull(3).comments.at(-1).body, /#7/);
  assert.ok(repo.find(1).labels.includes('task:status:needs-human-approval'));
});

test('a supersede run that delivered no pull request leaves the incumbents where they were', async () => {
  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])], [{ number: 3, head: { ref: 'claudinite/p/a/2026-08-13-old', sha: 'x' } }]);
  await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60, expected_outcome: 'supersede_existing_pr' })], {
    resolveTargetFor: async () => ({ mode: 'fresh', branch: 'claudinite/p/a/2026-08-14-new', pr: null, supersedes: [3], landed: null, reason: 'r' }),
    runTaskCodeWork: async () => ({ ok: true, agentRequested: false }),
  });
  assert.equal(repo.findPull(3).state, 'open');
  assert.equal(repo.find(1).state, 'closed');
});

// The previous delivery had concluded green and was never landed. Resolution
// lands it, and that IS this occurrence: the tree the run holds predates the
// merge, so nothing runs and the item closes done saying what landed.
test('a landed incumbent ends the occurrence without running the work', async () => {
  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])], [{ number: 2, head: { ref: 'claudinite/p/a/2026-08-12-older', sha: 'y' } }]);
  let ran = 0;
  const done = await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60, expected_outcome: 'supersede_existing_pr' })], {
    resolveTargetFor: async () => ({ mode: 'none', branch: null, pr: null, supersedes: [2], landed: 5, reason: 'landed #5' }),
    runTaskCodeWork: async () => { ran += 1; return { ok: true, agentRequested: false }; },
  });
  assert.equal(ran, 0);
  assert.deepEqual(done, [{ issue: 1, outcome: 'task:status:done' }]);
  const issue = repo.find(1);
  assert.equal(issue.state, 'closed');
  assert.match(issue.comments.at(-1).body, /#5/);
  assert.match(issue.comments.at(-1).body, /claudinite-task-exec v1 p\/a \[#1\] success/);
  assert.equal(repo.findPull(2).state, 'closed', 'the older incumbent is superseded by the landed one');
});

test('the hand-off stamps the target on the item, where the agent reads it', async () => {
  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])]);
  await drive(repo, [task('a', { expected_outcome: 'supersede_existing_pr' })], {
    resolveTargetFor: async () => ({ mode: 'fresh', branch: 'claudinite/p/a/2026-08-14-new', pr: null, supersedes: [3, 4], landed: null, reason: 'r' }),
    runTaskCodeWork: async () => ({ ok: true, agentRequested: true }),
  });
  const fields = parseWorkItemBody(repo.find(1).body);
  assert.equal(fields.targetBranch, 'claudinite/p/a/2026-08-14-new');
  assert.equal(fields.targetPr, null);
  assert.deepEqual(fields.supersedes, [3, 4], 'the agent\'s converge closes these once its own pull request exists');
});

test('a supersede already performed by code-work is not handed to the agent again', async () => {
  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])], [{ number: 3, head: { ref: 'claudinite/p/a/2026-08-13-old', sha: 'x' } }]);
  await drive(repo, [task('a', { code_work: 'node w.mjs', code_work_timeout: 60, expected_outcome: 'supersede_existing_pr' })], {
    resolveTargetFor: async () => ({ mode: 'fresh', branch: 'claudinite/p/a/2026-08-14-new', pr: null, supersedes: [3], landed: null, reason: 'r' }),
    runTaskCodeWork: async () => ({ ok: true, agentRequested: true, delivered: ['PR: #7 (open)'], openPr: 7, deliveredPr: 7 }),
  });
  assert.equal(repo.findPull(3).state, 'closed');
  assert.deepEqual(parseWorkItemBody(repo.find(1).body).supersedes, []);
  assert.equal(parseWorkItemBody(repo.find(1).body).targetBranch, 'claudinite/p/a/2026-08-14-new');
});

test('a target that could not be resolved parks the run, and nothing runs', async () => {
  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])]);
  let ran = 0;
  const done = await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60, expected_outcome: 'amend_existing_or_create_new_pr' })], {
    resolveTargetFor: async () => ({ error: 'could not list the open pull requests in o/r (500)' }),
    runTaskCodeWork: async () => { ran += 1; return { ok: true, agentRequested: false }; },
  });
  assert.equal(ran, 0);
  assert.deepEqual(done.map((d) => d.outcome), ['needs-human']);
  const issue = repo.find(1);
  assert.equal(issue.state, 'open');
  assert.ok(issue.labels.includes('task:status:needs-human-failure'));
  assert.match(issue.comments.at(-1).body, /could not list/);
});

test('a go verdict with agentless code_work closes the item task:status:done', async () => {
  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])]);
  const done = await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 })]);
  assert.deepEqual(done, [{ issue: 1, outcome: 'task:status:done' }]);
  const issue = repo.find(1);
  assert.equal(issue.state, 'closed');
  assert.ok(issue.labels.includes('task:status:done'));
  assert.equal(issue.labels.includes('task:status:running-executor'), false);
});

// A run that deliberately left an unmerged PR SUCCEEDED, but it is not finished:
// it is waiting on a reviewer, and closing it would hide that from every surface
// that counts open work. So it parks — the one park that is not a fault.
test('code_work that opened a PR parks the item for approval instead of closing', async () => {
  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])]);
  await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 })], {
    runTaskCodeWork: async () => ({ ok: true, agentRequested: false, delivered: ['PR: #7 (open)'], openPr: 7 }),
  });
  const issue = repo.find(1);
  assert.equal(issue.state, 'open');
  assert.ok(issue.labels.some((l) => l.startsWith('task:status:needs-human-')));
  assert.ok(issue.labels.includes('task:status:needs-human-approval'));
  assert.equal(issue.labels.includes('outcome:delivered'), false);
  assert.match(issue.comments.at(-1).body, /#7/);
});

// …and a delivered artifact that is NOT a PR awaiting a person — a branch, an
// already-merged PR — asks nobody for anything, so it still closes.
test('code_work that delivered no open PR still closes task:status:done', async () => {
  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])]);
  await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 })], {
    runTaskCodeWork: async () => ({ ok: true, agentRequested: false, delivered: ['Branch: `x`'], openPr: null }),
  });
  const issue = repo.find(1);
  assert.equal(issue.state, 'closed');
  assert.ok(issue.labels.includes('task:status:done'));
});

// A MARKED ISSUE is the person's own issue wearing the item's state, so its title is
// theirs and its fields ride a machine block. A DONE TERMINAL CLOSES IT ALL THE SAME
// (#1489): the run left nothing on it for anybody to act on.
const markedItem = (number, task, labels) => ({
  number, title: 'A thing to do', labels: ['task:origin:ad-hoc', ...labels],
  body: `Please do the thing.\n\n<!-- claudinite-item -->\npacks/p/tasks/${task}/task.md\n\nRequest: #${number}\n<!-- /claudinite-item -->\n`,
  created_at: '2026-08-14T04:00:00Z', updated_at: '2026-08-14T04:00:00Z',
});

test('a marked issue whose code_work is done is closed, like any other done item', async () => {
  const repo = fakeRepo([markedItem(1, 'a', ['task:status:waiting-for-executor'])]);
  const done = await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 })]);
  assert.deepEqual(done, [{ issue: 1, outcome: 'task:status:done' }]);
  const issue = repo.find(1);
  assert.equal(issue.state, 'closed');
  assert.ok(issue.labels.includes('task:status:done'));
  assert.ok(issue.labels.includes('task:origin:ad-hoc'), 'the mark never comes off — origins are for life');
});

// A REJECTED TERMINAL CLOSES THE ISSUE IT STANDS ON TOO (owner, 2026-09-06, #1835):
// a terminal is the end of the item, and both terminals end it the same way. What
// re-asks is what always re-asked — clearing the status.
test('a marked issue the precondition declined wears the refusal and is closed', async () => {
  const repo = fakeRepo([markedItem(2, 'a', ['task:status:waiting-for-executor'])]);
  const done = await drive(repo, [task('a', {}, term(() => ({ holds: false, reason: 'nothing to do' })))]);
  assert.deepEqual(done, [{ issue: 2, outcome: 'obsolete' }]);
  const issue = repo.find(2);
  assert.equal(issue.state, 'closed');
  assert.ok(issue.labels.includes('task:status:rejected'));
});

// A RUN THAT FAILED PARKS `failure`, whatever the worker asked for (#1452). The
// marker used to route the park, and a worker naming `action` moved a failed run into
// a non-blocking lane — so the standing slot freed and the task re-filed the next day
// against a cause nobody had fixed. ClaudiniteCanary reached SEVEN copies of one
// fleet-digest failure that way, hitbut twenty-two. A non-zero exit is a failure; the
// worker's verdict is preserved as the human-facing instruction in the comment, which
// is where it was always the useful half.
test('a failed code_work parks at failure, and still carries its worker\'s verdict', async () => {
  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])]);
  await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 })], {
    runTaskCodeWork: async () => ({ ok: false, why: 'code-work exited 1', triage: { kind: 'action', detail: 'PAT lacks Actions: write' } }),
  });
  const issue = repo.find(1);
  assert.ok(issue.labels.includes('task:status:needs-human-failure'), 'the run failed, so the park is failure');
  assert.ok(!issue.labels.includes('task:status:needs-human-action'), 'the worker cannot downgrade its own failure');
  assert.match(issue.comments.at(-1).body, /PAT lacks Actions: write/, 'the fix instruction survives');
  assert.match(issue.comments.at(-1).body, /action/, 'and so does the kind the worker asked for');
});

// No marker is not "assume the cheap lane": an unexplained break is a break.
test('a failed code_work that said nothing parks at failure', async () => {
  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])]);
  await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 })], {
    runTaskCodeWork: async () => ({ ok: false, why: 'code-work exited 1' }),
  });
  assert.ok(repo.find(1).labels.includes('task:status:needs-human-failure'));
});

// A WORKER MAY ASK TO COME BACK LATER (#1530). A production verification whose
// release has not landed yet is neither done nor broken: the run happened, found
// its subject absent, and prescribes its own wake. The executor stamps the item's
// `Not-before` and returns it to blocked — open, unparked, and released by the
// scheduler's ordinary readiness pass once the instant comes.
test('an ok code_work with a requeue ask re-arms Not-before and returns the item to blocked', async () => {
  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])]);
  const done = await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 })], {
    runTaskCodeWork: async () => ({
      ok: true, agentRequested: false,
      requeue: { until: '2026-08-15T04:20:00.000Z', reason: 'not yet live: mode unstamped' },
    }),
  });
  assert.deepEqual(done, [{ issue: 1, outcome: 'requeued' }]);
  const issue = repo.find(1);
  assert.equal(issue.state, 'open');
  assert.ok(issue.labels.includes('task:status:blocked'));
  assert.ok(!issue.labels.includes('task:status:running-executor'));
  assert.ok(!issue.labels.some((l) => l.startsWith('task:status:needs-human-')), 'a requeue is nobody\'s inbox');
  assert.equal(parseWorkItemBody(issue.body).notBefore, '2026-08-15T04:20:00.000Z');
});

// On a MARKED ISSUE the stamp must land in the machine block — `parseWorkItemBody`
// reads only that half, so a Not-before written into the person's prose would
// release the item on the very next pass.
test('a requeue on a marked issue stamps Not-before inside the machine block', async () => {
  const repo = fakeRepo([markedItem(3, 'a', ['task:status:waiting-for-executor'])]);
  await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 })], {
    runTaskCodeWork: async () => ({
      ok: true, agentRequested: false, requeue: { until: '2026-08-15T04:20:00.000Z', reason: 'not yet live' },
    }),
  });
  const issue = repo.find(3);
  assert.equal(issue.state, 'open');
  assert.ok(issue.labels.includes('task:status:blocked'));
  assert.equal(parseWorkItemBody(issue.body).notBefore, '2026-08-15T04:20:00.000Z');
  assert.match(issue.body, /<!-- claudinite-item -->[\s\S]*Not-before: 2026-08-15T04:20:00\.000Z[\s\S]*<!-- \/claudinite-item -->/,
    'the stamp is in the machine half, not the person\'s prose');
  assert.ok(issue.body.startsWith('Please do the thing.'), 'the person\'s own text is untouched');
});

// A requeue releases the claim the same way every let-go of an open item does:
// struck, so the next executor's claim wins on its first try.
test('a requeue strikes the executor\'s own claim', async () => {
  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])]);
  await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 })], {
    runTaskCodeWork: async () => ({
      ok: true, agentRequested: false, requeue: { until: '2026-08-15T04:20:00.000Z', reason: 'not yet live' },
    }),
  });
  const claim = repo.find(1).comments.find((c) => c.body.includes('<!-- claudinite-claim -->'));
  assert.match(claim.body, /<!-- claudinite-episode -->/, 'the spent claim carries the episode boundary');
});

// An ask the executor cannot honour — a marker whose instant did not parse — parks
// loudly instead of closing done: the worker said "wait" and silence would record
// a pass nobody measured.
test('a requeue ask with an unreadable instant parks at failure', async () => {
  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])]);
  await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 })], {
    runTaskCodeWork: async () => ({
      ok: true, agentRequested: false, requeue: { until: null, reason: 'huh' },
    }),
  });
  const issue = repo.find(1);
  assert.equal(issue.state, 'open');
  assert.ok(issue.labels.includes('task:status:needs-human-failure'));
  assert.match(issue.comments.at(-1).body, /requeue/i);
});

// A declared secret nobody configured is the definitive `action`: no code changes,
// somebody sets a value.
test('an unconfigured declared secret parks at action', async () => {
  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])]);
  await drive(repo, [task('a', { agent_model: 'none', code_work: 'node w.mjs', code_work_timeout: 60 })], {
    runTaskCodeWork: async () => ({ ok: true, agentRequested: false, missingSecrets: ['FLEET_GITHUB_TOKEN'] }),
  });
  assert.ok(repo.find(1).labels.includes('task:status:needs-human-action'));
});

// The roll is gone (#1115): a scheduled item's no-go CLOSES it with the reason
// on record — the next occurrence is the scheduler run's ask at the task's next
// anchor, and "asked, declined" lives on the schedule board, not on an open
// sleeping issue.
test('a no-go verdict closes a scheduled item with the reason — the roll is gone (#1115)', async () => {
  const repo = fakeRepo([workItem(1, 'a', ['task:status:waiting-for-executor'])]);
  const done = await drive(repo, [task('a', {}, term(() => ({ holds: false, reason: 'no work' })))]);
  assert.deepEqual(done, [{ issue: 1, outcome: 'obsolete' }]);
  const issue = repo.find(1);
  assert.equal(issue.state, 'closed');
  assert.ok(issue.labels.includes('task:status:rejected'));
  assert.equal(parseWorkItemBody(issue.body).notBefore, null, 'no Not-before is ever stamped');
  // The close comment carries the reason and points at the board — and for a
  // decline the record says success: the executor asked, got a no, closed.
