// THE FAKE CLOCK — virtual time and the ordered event queue every other fake
// module schedules on.
//
// It stands in for `src/world/clock.mjs`, so `port` carries exactly that
// module's names and nothing else; everything a scenario drives the clock WITH
// hangs off the harness object beside it. That split is what lets the parity
// guard compare key sets: a port that also carried `advanceTo` could never be
// checked against the real one.
//
// Time moves only when an event fires or a scenario advances it. There is no
// wall clock here at all — not a `setTimeout`, not a `Date.now()` — so a run is
// deterministic and a scenario spanning a fortnight costs microseconds.
//
// ORDERING IS TOTAL: strictly by instant, and FIFO within a tie. Two events
// scheduled for the same instant fire in the order they were scheduled, which is
// what makes a race a scenario can WRITE rather than one it has to hope for.

const ms = (when) => (typeof when === 'number' ? when : Date.parse(when));

export const MINUTE = 60_000;
export const HOUR = 60 * MINUTE;
export const DAY = 24 * HOUR;

export function makeClock({ start = '2026-08-12T00:00:00Z' } = {}) {
  let t = ms(start);
  let seq = 0;
  const queue = [];

  const port = {
    now: () => new Date(t),
    nowMs: () => t,
    nowIso: () => new Date(t).toISOString(),
  };

  // Fire `fn` at an absolute instant. An instant already past is scheduled at
  // the current one rather than silently dropped: a fake that "missed" it would
  // be modelling a platform behaviour nobody asked for.
  const at = (when, fn) => { queue.push({ t: Math.max(ms(when), t), seq: seq++, fn }); return harness; };
  const after = (deltaMs, fn) => at(t + deltaMs, fn);

  // Drain every event strictly before `to`, then park the clock AT `to`. Events
  // beyond it survive for a later segment — a scenario runs in phases to assert
  // a mid-state, and a queue emptied at each boundary would lose them.
  const runUntil = (to) => {
    const end = ms(to);
    for (;;) {
      queue.sort((a, b) => a.t - b.t || a.seq - b.seq);
      if (!queue.length || queue[0].t >= end) break;
      const ev = queue.shift();
      t = ev.t;
      ev.fn();
    }
    t = end;
    return harness;
  };

  const harness = {
    port,
    at,
    after,
    runUntil,
    // The instant, for a scenario that wants to compute one rather than read it
    // back off an artifact.
    ms: () => t,
    iso: () => port.nowIso(),
    // What has not fired yet — a scenario asserting that nothing is left, or
    // that something is still pending, reads this rather than the array.
    pending: () => queue.length,
  };
  return harness;
}

