      if (!holder) return { status: 404, json: null };
      if (method === 'POST') return { status: 201, json: postComment(holder, body.body) };
      const page = Number(q(path).get('page') ?? 1);
      return { status: 200, json: page === 1 ? holder.comments : [] };
    }

