      const i = issue(m[1]);
      if (!i) return { status: 404, json: null };
      let last = { status: 200, json: [] };
      for (const name of body.labels) last = addLabelTo(i, name);
      return last;
    }

    if ((m = /^\/repos\/[^/]+\/[^/]+\/issues\/(\d+)\/labels\/(.+)$/.exec(bare))) {
