    findPull: pull,
    issues: () => state.issues,
    pulls: () => state.pulls,
    labelDefs: () => state.labelDefs,
    dispatches: () => state.dispatches,
    calls: () => state.calls,
    onDispatch: (fn) => { onDispatch.push(fn); return harness; },
    scriptGraphql: (fn) => { graphql = fn; return harness; },

    // Direct writes, for seeding a world and for `humans.mjs`.
