+    if (/^\/repos\/[^/]+\/[^/]+\/releases\/latest$/.test(bare)) {
+      return state.releases ? { status: 200, json: state.releases } : { status: 404, json: null };
+    }
+
+    if ((m = /^\/repos\/[^/]+\/[^/]+\/actions\/variables\/([^/]+)$/.exec(bare))) {
+      const name = decodeURIComponent(m[1]);
