+      for (const fn of onDispatch) fn(fired);
+      return { status: 204, json: null };
+    }
+
+    if (/^\/search\/issues$/.test(bare)) {
+      const rows = state.issues.filter(visible);
+      return { status: 200, json: { total_count: rows.length, items: rows } };
+    }
