+  // --- store primitives ---------------------------------------------------
+
+  const issue = (n) => state.issues.find((i) => i.number === Number(n)) ?? null;
+  const pull = (n) => state.pulls.find((p) => p.number === Number(n)) ?? null;
+  const nextNumber = () => Math.max(0, ...state.issues.map((i) => i.number), ...state.pulls.map((p) => p.number)) + 1;
