51	  branches = {},
52	  commits = {},
53	  trees = {},
54	  releases = null,
55	  runsBySha = {},
56	} = {}) {
57	  const nowMs = () => (clock ? clock.ms() : 0);
58	  const nowIso = () => new Date(nowMs()).toISOString();
59	
60	  const state = {
61	    repo,
62	    issues: issues.map((i) => ({
63	      comments: [], state: 'open', labels: [], body: '', title: '',
64	      created_at: nowIso(), updated_at: nowIso(), ...i,
65	    })),
66	    pulls: pulls.map((p) => ({ comments: [], state: 'open', merged: false, ...p })),
67	    labelDefs: new Map(labels.map((l) => [l.name, { ...l }])),
68	    collaborators: { ...collaborators },
69	    variables: { ...variables },
70	    branches: { ...branches },
71	    commits: { ...commits },
72	    trees: { ...trees },
73	    releases,
74	    runsBySha: { ...runsBySha },
75	    // Every `workflow_dispatch` this repo accepted, in order — `actions.mjs`
