    await clock.runUntil('2026-08-12T02:00:00Z');
    assert.equal(agents.sessions().length, started ? 1 : 0, 'the fake knows; the caller does not');
  }
  assert.deepEqual(reports[0], reports[1]);
  assert.equal(reports[0].answered, false);
});

